import { mkdir, rm, writeFile } from "node:fs/promises";
import path from "node:path";

/**
 * File storage behind an interface (SPEC §0, §1): callers never assume files
 * live on local disk, so another backend can be added later without touching
 * them. Keys are generated by the server (never from user file names).
 */
export interface Storage {
  /** Stores `data` under `key`; returns its public URL. */
  put(key: string, data: Buffer, contentType: string): Promise<string>;
  /** Deletes the file behind a URL this storage returned; unknown URLs are ignored. */
  deleteUrl(url: string): Promise<void>;
}

/** `listings/42/3f9c…-thumb.webp`: lowercase letters, digits, `-`, `_`, one extension. */
const KEY = /^[a-z0-9][a-z0-9_-]*(\/[a-z0-9][a-z0-9_-]*)*\.[a-z0-9]+$/;

export class InvalidStorageKeyError extends Error {
  constructor() {
    super("invalid storage key");
  }
}

/**
 * Files on the VPS disk under `rootDir` (UPLOAD_DIR), served at `publicPrefix`
 * (`/uploads`: Express in development, Caddy in production).
 */
export class LocalDiskStorage implements Storage {
  private readonly root: string;

  constructor(
    rootDir: string,
    private readonly publicPrefix = "/uploads",
  ) {
    this.root = path.resolve(rootDir);
  }

  private fileFor(key: string): string {
    if (!KEY.test(key)) throw new InvalidStorageKeyError();
    const file = path.resolve(this.root, key);
    // Defence in depth: the key pattern already excludes "..".
    if (!file.startsWith(this.root + path.sep)) throw new InvalidStorageKeyError();
    return file;
  }

  async put(key: string, data: Buffer, _contentType: string): Promise<string> {
    const file = this.fileFor(key);
    await mkdir(path.dirname(file), { recursive: true });
    await writeFile(file, data, { flag: "wx" }); // never overwrite
    return `${this.publicPrefix}/${key}`;
  }

  async deleteUrl(url: string): Promise<void> {
    const prefix = `${this.publicPrefix}/`;
    if (!url.startsWith(prefix)) return;
    const key = url.slice(prefix.length);
    if (!KEY.test(key)) return;
    await rm(this.fileFor(key), { force: true });
  }
}
